<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {call,ensureGuest,uid,delay,ApiError} from '../../services/api'
import {downloadOriginal} from '../../services/files'

const meta=ref<any>(null),history=ref<any[]>([]),messages=ref<any[]>([]),result=ref<any>(null)
const session=ref(''),revision=ref(0),topic=ref(''),question=ref(''),busy=ref(false),error=ref('')
const panel=ref(''),sourceDoc=ref<any>(null),policyList=ref<any[]>([]),policyQuery=ref(''),draft=ref('')
const fields=ref<Record<string,any>>({}),simulation=ref(false),scrollTarget=ref(''),activeTurn=ref('')
const currentTopic=computed(()=>meta.value?.topics?.find((t:any)=>t.id===topic.value))
const topics=computed(()=>meta.value?.topics||[])
const names:Record<string,string>={SAI:'人工智能学院',MARX:'马克思主义学院',CSE:'计算机学院',CYBER:'国家网络安全学院',undergraduate:'本科',master:'硕士',doctor:'博士',full_time:'全日制',part_time:'非全日制',academic:'学术学位',professional:'专业学位',ordinary:'普通班',self_strength:'人工智能自强班',excellent:'优秀',good:'良好',pass:'合格',fail:'不合格'}
const formDefs:any[]=[
 {key:'college',label:'所在学院',choices:['SAI','MARX','CSE','CYBER']},
 {key:'program_level',label:'学历层次',choices:['undergraduate','master','doctor']},
 {key:'study_mode',label:'培养方式',choices:['full_time','part_time']},
 {key:'degree_type',label:'学位类型',choices:['academic','professional']},
 {key:'cohort_year',label:'入学年份',number:true},
 {key:'year_of_study',label:'当前就读年级',number:true},
 {key:'class_type',label:'本科班型',choices:['ordinary','self_strength']},
 {key:'academic_rank_pct',label:'学习成绩排名 前 %',number:true},
 {key:'comprehensive_rank_pct',label:'综合测评排名 前 %',number:true},
 {key:'achievement_eligible',label:'成果已按对应条款核对',boolean:true},
 {key:'has_exclusion',label:'存在通知列举的禁止参评情形',boolean:true},
 {key:'previous_leijun',label:'曾获雷军计算机本科生奖学金',boolean:true},
 {key:'another_special_award',label:'本年度已有其他专项奖学金',boolean:true},
 {key:'english_eligible',label:'外语符合对应通知要求',boolean:true},
 {key:'midterm_result',label:'中期考核结果',choices:['excellent','good','pass','fail']},
 {key:'major',label:'专业（学生自述）',text:true,maxlength:80},
 {key:'achievements',label:'成果自述（不自动认定符合条件）',text:true,maxlength:600}
]
const visibleFields=computed(()=>{const need=new Set(result.value?.missing_fields||[]);if(!need.size)return formDefs;return [...formDefs].sort((a,b)=>Number(need.has(b.key))-Number(need.has(a.key)))})
const profileSummary=computed(()=>formDefs.filter(d=>fields.value[d.key]!==undefined&&fields.value[d.key]!==null).map(d=>({label:d.label,value:display(fields.value[d.key])})))
const decisionNames:Record<string,string>={information:'政策信息',needs_information:'待补充条件',not_met:'存在不满足项',preliminary_match:'已编码条件初步匹配',needs_human:'需要人工确认',evidence_only:'政策原文检索'}
function display(value:any){return value===true?'是':value===false?'否':(names[value]||String(value))}
function options(d:any){return [{label:'待确认',value:null},...(d.boolean?[{label:'是',value:true},{label:'否',value:false}]:d.choices.map((v:any)=>({label:display(v),value:v})))]}
function selected(d:any,e:any){fields.value[d.key]=options(d)[Number(e.detail.value)].value}
function setNumber(key:string,event:any){const value=event.detail.value;fields.value[key]=value===''?null:Number(value)}
function setText(key:string,event:any){fields.value[key]=event.detail.value||null}
function toggleSimulation(event:any){simulation.value=Boolean(event.detail?.value)}
function toBottom(){scrollTarget.value='';setTimeout(()=>scrollTarget.value='chat-bottom',80)}
async function init(){try{meta.value=await call('/api/v1/meta');await ensureGuest();await refreshHistory()}catch(e:any){if(e.status===401){uni.removeStorageSync('policy_token');uni.removeStorageSync('policy_token_expires');clearSessionView();history.value=[];try{await ensureGuest();await refreshHistory();error.value='旧本机身份已失效，已创建新的试用身份。'}catch(next:any){error.value=next.message}}else error.value=e.message}}
function confirmAction(content:string):Promise<boolean>{return new Promise(resolve=>uni.showModal({title:'本机试用记录',content,success:r=>resolve(r.confirm),fail:()=>resolve(false)}))}
async function clearHistory(){if(busy.value)return;if(!await confirmAction('将永久清空当前本机身份的全部咨询与人工草稿，政策原件不会删除。是否继续？'))return;try{await call('/api/v1/sessions','DELETE');newChat();history.value=[];panel.value='about';uni.showToast({title:'咨询记录已清空',icon:'none'})}catch(e:any){error.value=e.message;panel.value=''}}
async function logout(){if(busy.value)return;if(!await confirmAction('退出后将撤销当前本机身份，已有记录无法通过新的访客身份找回。需要清除记录时请先使用“清空咨询记录”。是否退出？'))return;try{await call('/api/v1/auth/logout','POST');uni.removeStorageSync('policy_token');uni.removeStorageSync('policy_token_expires');newChat();history.value=[];await ensureGuest();panel.value='';uni.showToast({title:'已退出并创建新试用身份',icon:'none'})}catch(e:any){error.value=e.message;panel.value=''}}
async function refreshHistory(){history.value=await call('/api/v1/sessions')}
function clearSessionView(id=''){topic.value=id;session.value='';revision.value=0;messages.value=[];result.value=null;fields.value={};question.value='';draft.value='';sourceDoc.value=null;error.value='';activeTurn.value=''}
function newChat(id=''){if(busy.value)return;clearSessionView(id)}
async function openHistory(id:string){if(busy.value)return;try{const s=await call('/api/v1/sessions/'+id);session.value=id;revision.value=s.revision;topic.value=s.topic||'';fields.value=Object.fromEntries(Object.entries(s.profile).filter(([k])=>!k.startsWith('_')));messages.value=[];for(let i=0;i<s.messages.length;i++){const m=s.messages[i];messages.value.push({role:'user',text:m.text});const turn=s.turns[i];if(turn?.result)messages.value.push({role:'assistant',result:turn.result});}result.value=[...s.turns].reverse().find((t:any)=>t.result)?.result||null;panel.value='';toBottom()}catch(e:any){error.value=e.message}}
async function poll(tid:string){for(let i=0;i<120;i++){const r=await call('/api/v1/turns/'+tid);if(r.state==='COMPLETED'){const a=r.result;result.value=a;revision.value=a.profile_revision;topic.value=a.topic||topic.value;fields.value=Object.fromEntries(Object.entries(a.profile).filter(([k])=>!k.startsWith('_')));messages.value.push({role:'assistant',result:a});activeTurn.value='';await refreshHistory();toBottom();return}if(['FAILED','STALE'].includes(r.state))throw new Error(r.error||'当前资料已改变，请重新提交');await delay(900)}throw new Error('处理时间较长，可点击“继续查看处理结果”，无需重复发送。')}
async function send(text?:string,patch?:Record<string,any>){const value=(typeof text==='string'?text:question.value).trim();if(!value||busy.value)return;busy.value=true;error.value='';try{const fresh=await ensureGuest();if(fresh&&session.value){clearSessionView(topic.value);history.value=[]}if(!session.value){const s=await call('/api/v1/sessions','POST',{topic:topic.value||null});session.value=s.session_id;revision.value=0}const payload:any={text:value,client_message_id:uid(),expected_profile_revision:revision.value,channel:'h5',profile_patch:patch||{},topic:topic.value||null}
 // #ifdef MP-WEIXIN
 payload.channel='mp_weixin'
 // #endif
 if(simulation.value)payload.simulation_time='2026-10-24T10:00:00+08:00';question.value='';messages.value.push({role:'user',text:value});toBottom();const r=await call('/api/v1/sessions/'+session.value+'/messages','POST',payload);activeTurn.value=r.turn_id;await poll(r.turn_id)}catch(e:any){error.value=e.message;if(e.status===401){uni.removeStorageSync('policy_token');uni.removeStorageSync('policy_token_expires');clearSessionView();history.value=[];error.value='当前本机身份已过期或退出，请重新开始咨询。'}}finally{busy.value=false}}
async function continueTurn(){if(!activeTurn.value||busy.value)return;busy.value=true;error.value='';try{await poll(activeTurn.value)}catch(e:any){error.value=e.message}finally{busy.value=false}}
function saveProfile(){const patch:Record<string,any>={};for(const d of formDefs){const v=fields.value[d.key];if(v!==undefined)patch[d.key]=v}panel.value='';send('请根据我确认的资料重新核对申请条件。',patch)}
async function source(s:any){try{sourceDoc.value=await call('/api/v1/policies/'+s.policy_key+'/versions/'+s.version_id);panel.value='source'}catch(e:any){error.value=e.message}}
async function loadPolicies(){try{await ensureGuest();policyList.value=await call('/api/v1/policies?q='+encodeURIComponent(policyQuery.value));panel.value='policies'}catch(e:any){error.value=e.message}}
async function policy(p:any){try{sourceDoc.value=await call('/api/v1/policies/'+p.key+'/versions/current');panel.value='source'}catch(e:any){error.value=e.message}}
async function handoff(){if(!session.value){uni.showToast({title:'先开始一次咨询',icon:'none'});return}try{const r=await call('/api/v1/handoffs/drafts','POST',{session_id:session.value});draft.value=r.text;panel.value='handoff'}catch(e:any){error.value=e.message}}
async function download(key:string){try{await downloadOriginal(key);uni.showToast({title:'已请求打开原件',icon:'none'})}catch(e:any){uni.showToast({title:e.message||'无法打开原件',icon:'none',duration:3000})}}
function copyDraft(){uni.setClipboardData({data:draft.value})}
function sample(s:string){question.value=s;send()}
onMounted(init)
</script>

<template>
 <view class="app-shell">
  <view class="topbar"><view class="brand"><view class="brand-mark">策</view><view><text class="brand-name">珞策</text><text class="brand-sub">学生政策助手</text></view></view><view class="top-actions"><text class="connected"><text class="dot"/>{{meta?'本地服务已连接':'连接服务中'}}</text><button class="plain-button" @click="panel='about'">试用说明</button></view></view>
  <view class="trial-banner">本地试用 · 政策副本待业务复核 <text class="banner-detail">{{meta?.llm_configured?'模型接口已配置，结论仍需核验':meta?.local_llm_available?'本地轻量模型辅助取证，申请条件由程序核对':'当前使用政策检索与程序条件核对，大模型尚未连接'}}</text></view>
  <view v-if="simulation" class="simulation-banner">历史回放：2026 年 10 月 24 日 · 以下结果不代表当前仍可办理 <button class="text-button" @click="simulation=false">退出回放</button></view>
  <view class="workspace">
   <view class="sidebar">
    <button class="new-chat" @click="newChat()">＋ 开始新的咨询</button>
    <text class="section-label">办事导航</text>
    <view class="topic-list"><button v-for="(t,index) in topics" :key="t.id" :class="['topic-item',{selected:topic===t.id}]" @click="newChat(t.id)"><text class="topic-number">0{{index+1}}</text><view><text class="topic-title">{{t.name}}</text><text class="topic-sub">{{t.category}}</text></view><text class="topic-arrow">›</text></button></view>
    <button class="library-button" @click="loadPolicies">▤ 政策原文库 <text>{{meta?.documents||'—'}}</text></button>
    <view class="history-heading"><text class="section-label">本机试用记录</text><text class="tiny">{{history.length}} 条</text></view>
    <scroll-view scroll-y class="history-list"><button v-for="h in history" :key="h.id" :class="['history-item',{active:session===h.id}]" @click="openHistory(h.id)">{{h.title}}</button><text v-if="!history.length" class="empty-history">咨询开始后，记录会保存在本机身份下。</text></scroll-view>
    <view class="sidebar-footer"><text class="footer-title">有依据，才有下一步。</text><text>理解条件 · 理清流程 · 查阅原文</text></view>
   </view>

   <view class="chat-panel">
    <view class="chat-header"><view><text class="eyebrow">CAMPUS POLICY GUIDE</text><text class="chat-title">{{currentTopic?.name||'把复杂政策，变成清楚的下一步。'}}</text></view><button class="profile-button" @click="panel='profile'">我的条件 <text v-if="profileSummary.length">{{profileSummary.length}}</text></button></view>
    <scroll-view scroll-y class="chat-scroll" :scroll-into-view="scrollTarget" scroll-with-animation>
     <view v-if="!messages.length" class="welcome">
      <view class="welcome-symbol">策</view><text class="welcome-title">你的校园办事向导</text><text class="welcome-text">告诉我你想办理的事项。必要时，我会补问关键条件，<br/>再把适用条款、材料和流程整理给你。</text>
      <view class="sample-grid"><button class="sample-card" @click="sample('我想了解雷军计算机本科生奖学金的申请条件和材料。')"><text class="sample-tag">奖学金申请</text><text>雷军奖学金需要满足哪些条件？</text><text class="sample-arrow">↗</text></button><button class="sample-card" @click="sample('我是人工智能学院2025级学术学位硕士，中期考核需要准备什么？')"><text class="sample-tag">培养与考核</text><text>中期考核有哪些步骤和材料？</text><text class="sample-arrow">↗</text></button><button class="sample-card" @click="sample('马院硕博连读的个人申请截止和考核时间分别是什么？')"><text class="sample-tag">硕博连读</text><text>个人申请和学院考核时间怎么区分？</text><text class="sample-arrow">↗</text></button></view>
      <view class="trust-row"><text>✓ 按需补问</text><text>✓ 条件逐项核对</text><text>✓ 原文可查</text></view>
     </view>
     <view v-for="(m,index) in messages" :key="index" :class="['message',m.role]">
      <view v-if="m.role==='user'" class="user-bubble">{{m.text}}</view>
      <template v-else><view class="assistant-label"><view class="mini-mark">策</view><text>珞策 · 政策与条件核对</text></view><view class="answer"><view class="answer-top"><text :class="['status',m.result.decision]">{{decisionNames[m.result.decision]||'政策信息'}}</text><text v-if="m.result.simulation" class="status historical">历史回放</text></view><text class="answer-summary">{{m.result.summary}}</text>
       <view v-if="m.result.window_status?.raw" class="deadline"><text class="deadline-label">原通知个人申请时限</text><text>{{m.result.window_status.raw}}</text><text class="deadline-note">{{m.result.window_status.note}}</text></view>
       <view v-if="m.result.questions?.length" class="question-box"><text v-for="q in m.result.questions" :key="q">{{q}}</text><button class="small-primary" @click="result=m.result;panel='profile'">补充或确认条件</button></view>
       <view v-if="m.result.condition_results?.length" class="conditions"><view v-for="c in m.result.condition_results" :key="c.name" class="condition-row"><text :class="['condition-sign',c.status]">{{c.status==='pass'?'✓':c.status==='fail'?'×':'?'}}</text><view><text class="condition-name">{{c.name}}</text><text class="condition-detail">{{c.detail}}</text></view><text :class="['condition-state',c.status]">{{c.status==='pass'?'初步满足':c.status==='fail'?'不满足':'待确认'}}</text></view></view>
       <view v-if="m.result.model_explanation" class="model-explanation"><text class="small-heading">模型选取的政策原文 · 待业务核验</text><text>{{m.result.model_explanation.summary}}</text></view>
       <view class="sources-inline"><text class="small-heading">本轮政策依据</text><button v-for="s in m.result.sources.slice(0,3)" :key="s.source_id" class="source-link" @click="source(s)"><text class="source-icon">文</text><view><text>{{s.title}}</text><text class="source-locator">{{s.locator}}</text></view><text>›</text></button></view>
       <view class="answer-bottom"><text>依据整理副本 · 申请及评审结果以经办部门审核为准</text></view>
      </view></template>
     </view>
     <view v-if="busy" class="busy"><view class="pulse"/><text>正在检索政策、核对条件与出处…</text></view>
     <view id="chat-bottom" class="chat-bottom"/>
    </scroll-view>
    <view v-if="error" class="error"><text>{{error}}</text><button v-if="activeTurn&&!busy" class="text-button" @click="continueTurn">继续查看处理结果</button><button v-if="!meta" class="text-button" @click="init">重新连接</button></view>
    <view class="composer-area"><view class="composer"><textarea v-model="question" class="question-input" placeholder="例如：我是人工智能学院大二学生，想了解奖学金申请条件…" :maxlength="4000" :disabled="busy" confirm-type="send" @confirm="send()"/><button class="send-button" :disabled="busy||!question.trim()" @click="send()">{{busy?'处理中':'发送 ↑'}}</button></view><view class="composer-note"><text>无需填写学号或身份证等身份材料。</text><button class="text-button" @click="handoff">需要老师帮助 ›</button></view></view>
   </view>

   <view class="guide-panel"><view class="guide-heading"><text class="eyebrow">YOUR NEXT STEPS</text><text class="guide-title">本次办事指引</text></view><scroll-view scroll-y class="guide-scroll"><view v-if="!result" class="guide-empty"><view class="guide-illustration"><view class="paper-line"/><view class="paper-line short"/><view class="paper-line"/><view class="paper-check">✓</view></view><text>咨询后，在这里查看</text><text class="guide-empty-details">办理流程、材料清单<br/>和仍需确认的事项。</text></view><template v-else>
     <view class="guide-section"><text class="small-heading">办理流程</text><view v-for="(s,i) in result.steps" :key="i" class="step"><text class="step-index">{{i+1}}</text><view><text class="step-title">{{s.name}}</text><text class="step-detail">{{s.detail}}</text></view></view><text v-if="!result.steps.length" class="muted">条件或事项确认后，提供相应流程。</text></view>
     <view class="guide-section"><text class="small-heading">材料与表格</text><text v-if="!result.materials_complete" class="material-warning">完整材料依据尚未补齐</text><view v-for="(m,i) in result.materials" :key="i" class="material"><text class="material-name">▤ {{m.name}}</text><text class="muted">{{m.status}}</text><button v-if="m.attachment_key" class="text-button" @click="download(m.attachment_key)">查看 / 下载原件 ↗</button></view><text v-if="!result.materials.length" class="muted">当前尚未形成材料清单。</text></view>
     <view class="guide-section"><text class="small-heading">仍需确认</text><text v-for="(item,i) in result.unresolved_items" :key="i" class="unresolved">{{item}}</text><button class="handoff-button" @click="handoff">生成给老师的咨询摘要</button></view>
    </template></scroll-view><view class="guide-footer"><text>{{meta?.parsed||'—'}} 份文本已解析 · 原件可追溯</text><text>当前知识与规则均待业务审核</text></view></view>
  </view>

  <view class="mobile-actions"><button class="plain-button" @click="panel='topics'">选择事项</button><button class="plain-button" @click="panel='guide'">办事指引</button><button class="plain-button" @click="loadPolicies">政策原文</button><button class="plain-button" @click="panel='history'">本机记录</button></view>

  <view v-if="panel" class="overlay" @click.self="panel=''">
   <view :class="['modal',{wide:panel==='source'}]"><view class="modal-head"><text>{{({profile:'确认我的条件',source:'政策原文',policies:'政策原文库',handoff:'给老师的咨询摘要',about:'试用说明',topics:'选择办理事项',history:'本机试用记录',guide:'本次办事指引'} as any)[panel]}}</text><button class="close" @click="panel=''">×</button></view><scroll-view scroll-y class="modal-scroll">
    <template v-if="panel==='profile'"><text class="modal-intro">按当前事项填写必要信息，未知项保持“待确认”。涉及成果及禁止情形，请对照政策条款核实。</text><view class="profile-grid"><view v-for="d in visibleFields" :key="d.key" class="form-field"><text :class="{needed:result?.missing_fields?.includes(d.key)}">{{d.label}} <text v-if="result?.missing_fields?.includes(d.key)">· 待补充</text></text><input v-if="d.number" type="digit" :value="fields[d.key]??''" placeholder="待确认" @input="setNumber(d.key,$event)"/><input v-else-if="d.text" type="text" :maxlength="d.maxlength" :value="fields[d.key]??''" placeholder="可选填写" @input="setText(d.key,$event)"/><picker v-else :range="options(d)" range-key="label" @change="selected(d,$event)"><view class="picker-value">{{fields[d.key]===undefined||fields[d.key]===null?'待确认':display(fields[d.key])}} <text>⌄</text></view></picker></view></view><button class="primary modal-primary" :disabled="busy" @click="saveProfile">确认资料并重新匹配</button></template>
    <template v-if="panel==='source'&&sourceDoc"><text class="document-title">{{sourceDoc.title}}</text><view class="document-meta">用户提供的政策副本 · 待业务复核</view><text selectable class="document-text">{{sourceDoc.text||'文本尚未解析，请查看原件。'}}</text><button class="secondary" @click="download(sourceDoc.key)">查看 / 下载原件</button></template>
    <template v-if="panel==='policies'"><view class="search-bar"><input v-model="policyQuery" placeholder="搜索政策标题" @confirm="loadPolicies"/><button class="small-primary" @click="loadPolicies">搜索</button></view><button v-for="p in policyList" :key="p.key" class="policy-row" @click="policy(p)"><text>{{p.title}}</text><text>›</text></button><text v-if="!policyList.length" class="muted">没有匹配标题。</text></template>
    <template v-if="panel==='handoff'"><text class="modal-intro">以下摘要尚未发送。请先核对内容，再自行提供给对应学院经办老师。</text><text selectable class="draft-text">{{draft}}</text><button class="primary" @click="copyDraft">复制咨询摘要</button></template>
    <template v-if="panel==='topics'"><button v-for="t in topics" :key="t.id" class="policy-row" @click="newChat(t.id);panel=''">{{t.name}} ›</button></template>
    <template v-if="panel==='history'"><button v-for="h in history" :key="h.id" class="policy-row" @click="openHistory(h.id)">{{h.title}} ›</button><text v-if="!history.length" class="muted">暂无咨询记录。</text></template>
    <template v-if="panel==='guide'"><text v-if="!result" class="muted">先开始一次咨询。</text><template v-else><text class="document-title">{{result.summary}}</text><text v-for="(s,i) in result.steps" :key="i" class="unresolved">{{i+1}}. {{s.name}}：{{s.detail}}</text><text class="small-heading">材料清单</text><text v-for="(m,i) in result.materials" :key="i" class="unresolved">{{m.name}} · {{m.status}}</text><text v-for="(item,i) in result.unresolved_items" :key="i" class="unresolved">{{item}}</text><button class="primary" @click="handoff">生成咨询摘要</button></template></template>
    <template v-if="panel==='about'"><text class="document-title">当前为本地试用版本</text><text class="unresolved">已连接真实政策副本、混合检索和程序规则。政策内容与已编码规则尚待业务人员核验，结果用于项目开发与演示。</text><text class="unresolved">{{meta?.llm_configured?'已配置模型接口，模型取证仍需业务核验。':meta?.local_llm_available?'本机已下载轻量模型辅助选择政策证据，问题和资料保留在本机。模型规模有限，资格结论由规则核对，最终须经业务审核。':'尚未配置大模型 API。当前不会向外部大模型发送你的问题或资料。'}}</text><text class="unresolved">网页与微信小程序共用后端。小程序账号、正式域名和真机发布须另行配置，本地身份不会自动跨端同步。</text><view class="simulation-control"><text>演示历史办理条件</text><switch :checked="simulation" color="#174d40" @change="toggleSimulation"/></view><text class="muted">启用后使用 2026-10-24 的明确回放日期，结果会显示历史回放标识。</text><text class="unresolved">本地身份有效期24小时。退出会撤销凭证；清空记录仅删除当前身份的咨询与草稿，不删除政策原件。</text><button class="secondary" :disabled="busy" @click="clearHistory">清空我的咨询记录</button><button class="secondary" :disabled="busy" @click="logout">退出本机试用身份</button></template>
   </scroll-view></view>
  </view>
 </view>
</template>

